func:
// Optional: whether an imaging app has SQMeter's Alpaca devices connected,
// and the device's sun altitude. Neither is on MQTT, so they're read over
// HTTP. Set SQMETER_HOST on this flow (double-click the tab) to turn it on.
const host = String(env.get('SQMETER_HOST') || '').trim();
if (!host) {
  node.status({ fill: 'grey', shape: 'ring', text: 'off - set SQMETER_HOST on the flow' });
  return null;
}
node.status({ fill: 'green', shape: 'dot', text: `polling ${host}` });
const base = `http://${host}`;
return [[
  { topic: 'poll/safetymonitor', url: `${base}/api/v1/safetymonitor/0/connected` },
  { topic: 'poll/observingconditions', url: `${base}/api/v1/observingconditions/0/connected` },
  { topic: 'poll/status', url: `${base}/api/status` },
]];

// SQMeter -> flat topics with one number each, retained, for indi-allsky.
// Fed by SQMeter's MQTT topics and, optionally, an HTTP poll for whether an
// imaging app is connected (that isn't published on MQTT).
const OUT = 'indi/mysqm/';
const out = [];
const send = (name, value, prefix = OUT) => {
  if (value !== null && value !== undefined) out.push({ topic: prefix + name, payload: value, retain: true });
};
const num = (v, d) => (typeof v === 'number' && Number.isFinite(v) ? Number(v.toFixed(d)) : null);
const flag = (v) => (typeof v === 'boolean' ? (v ? 1 : 0) : null);

let p = msg.payload;
if (typeof p === 'string' && /^[[{]/.test(p.trim())) {
  try {
    p = JSON.parse(p);
  } catch (e) {
    node.error('SQMeter sent JSON that could not be read', msg);
    return null;
  }
}
const topic = String(msg.topic || '');
const source = topic.split('/').pop();

if (source === 'state') {
  // A group whose status isn't "ok" carries no readings: its topics are skipped.
  const ok = (group) => (p[group] && p[group].status === 'ok' ? p[group] : {});
  const sky = ok('sky'), light = ok('light'), env = ok('environment'), ir = ok('infrared');
  const clouds = ok('clouds'), rain = ok('rain'), wind = ok('wind'), gps = ok('gps');
  const condition = { clear: 0, cloudy: 1, overcast: 2 }[clouds.condition];
  const v = {
    sqm: num(sky.sqm, 2),
    bortle: num(sky.bortle, 0),
    nelm: num(sky.nelm, 2),
    lux: num(light.lux, 6),
    ambient: num(env.temperature, 1),
    humidity: num(env.humidity, 1),
    dewpoint: num(env.dewpoint, 1),
    pressure: num(env.pressure, 1),
    cloudcover: num(clouds.coverPercent, 0),
    skystate_code: condition === undefined ? null : condition,
    raining: flag(rain.raining),
    rainrate: num(rain.intensity, 2),
    windspd: num(wind.speed, 1),
    windgust: num(wind.gust, 1),
    // The device leaves this out when it's calm or there's no vane.
    winddir: num(wind.direction, 0),
    skyambient: num(ir.ambientTemperature, 1),
    skyobject: num(ir.skyTemperature, 1),
    gps_fix: flag(gps.fix),
    latitude: gps.fix ? num(gps.latitude, 5) : null,
    longitude: gps.fix ? num(gps.longitude, 5) : null,
    data_age: typeof p.dataAgeMs === 'number' ? num(p.dataAgeMs / 1000, 1) : null,
    stale: flag(p.dataStale),
    last_update: Math.round(Date.now() / 1000),
  };
  for (const [name, value] of Object.entries(v)) send(name, value);
  // Text versions for other consumers (indi-allsky only reads numbers).
  send('bortle_label', v.bortle !== null ? `B${v.bortle}` : null);
  send('skystate', clouds.condition || null);
  send('json', JSON.stringify(v));
  // The IR sensor's two temperatures under their older names.
  send('infrared_ambientTemp', v.skyambient, 'indi/sqmeter/');
  send('infrared_skyTemp', v.skyobject, 'indi/sqmeter/');
  context.set('summary', `SQM ${v.sqm ?? '--'} | ${v.ambient ?? '--'}°C | Cloud ${v.cloudcover ?? '--'}%`);
  context.set('raining', v.raining);
} else if (source === 'safety') {
  send('safe', flag(p.safe));
  send('seconds_until_safe', num(p.secondsUntilSafe, 0));
  send('unsafe_flags', num(p.reasonFlags, 0));
  send('unsafe_reasons', Array.isArray(p.reasons) ? (p.reasons.length ? p.reasons.join(', ') : 'none') : null);
  context.set('safe', p.safe);
} else if (source === 'armed') {
  send('alerts_armed', String(p).trim() === '1' ? 1 : 0);
} else if (source === 'availability') {
  send('online', String(p).trim() === 'online' ? 1 : 0);
} else if (topic === 'poll/safetymonitor' || topic === 'poll/observingconditions') {
  // Alpaca GET .../connected answers {"Value": true|false, ...}
  const connected = msg.statusCode === 200 && p && typeof p.Value === 'boolean' ? p.Value : null;
  const name = topic === 'poll/safetymonitor' ? 'imaging_safetymonitor' : 'imaging_weather';
  context.set(name, connected);
  send(name, flag(connected));
  const sm = context.get('imaging_safetymonitor');
  const oc = context.get('imaging_weather');
  if (sm !== undefined && oc !== undefined && (sm !== null || oc !== null)) send('imaging', sm || oc ? 1 : 0);
} else if (topic === 'poll/status') {
  const sky = (msg.statusCode === 200 && p && p.sky) || {};
  send('sun_alt', num(sky.sunAltitudeDeg, 1));
  send('is_night', flag(sky.isNight));
} else {
  return null;
}

const safe = context.get('safe');
node.status({
  fill: context.get('raining') ? 'red' : safe === false ? 'yellow' : 'green',
  shape: 'dot',
  text: `${context.get('summary') || 'waiting for readings'}${safe === undefined ? '' : safe ? ' | safe' : ' | UNSAFE'} | ${new Date().toLocaleTimeString('en-GB', { hour12: false })}`,
});
return [out];
